 "src/Code.gs": "/**\n * Google Apps Script bound to the schedule spreadsheet.\n *\n * Sheet layout (row 1 is a header):\n *   A: shift start (Date)   B: shift end (Date)   C: status (\"Added\" once synced)\n *\n * Columns A and B are filled by the parsing formulas (see parseShift.js).\n * Run createWorkSchedule() from the Apps Script editor or a time-driven trigger.\n */\nconst EVENT_TITLE = 'Work';\nconst REMINDER_MINUTES = 60;\nconst STATUS_COL = 3;\n\nfunction createWorkSchedule() {\n  const sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();\n  const values = sheet.getDataRange().getValues();\n  const calendar = CalendarApp.getDefaultCalendar();\n  const summary = { added: 0, skipped: 0, failed: 0 };\n\n  for (let i = 1; i < values.length; i++) {\n    const [start, end, status] = values[i];\n\n    // Already synced on a previous run: running the script twice must not\n    // create duplicate events.\n    if (status === 'Added') { summary.skipped++; continue; }\n\n    // Formula errors and blank rows come through as strings or empty cells.\n    if (!(start instanceof Date) || !(end instanceof Date) || end <= start) {\n      summary.skipped++;\n      continue;\n    }\n\n    try {\n      const event = calendar.createEvent(EVENT_TITLE, start, end);\n      event.addPopupReminder(REMINDER_MINUTES);\n      sheet.getRange(i + 1, STATUS_COL).setValue('Added');\n      summary.added++;\n    } catch (e) {\n      Logger.log(`Row ${i + 1}: failed to create event: ${e}`);\n      summary.failed++;\n    }\n  }\n\n  Logger.log(`Added ${summary.added}, skipped ${summary.skipped}, failed ${summary.failed}`);\n  return summary;\n}\n\nif (typeof module !== 'undefined') module.exports = { createWorkSchedule };\n",
 "src/parseShift.js": "/**\n * Parses one Synerion schedule cell, e.g. \"3/31 - 13:00-21:15\", into start and\n * end Date objects. This is the same logic as the Google Sheets formulas:\n *\n *   Start: =C2+TIMEVALUE(LEFT(D2, FIND(\"-\", D2) - 1))\n *   End:   =C2+TIMEVALUE(MID(D2, FIND(\"-\", D2) + 1, LEN(D2)))\n *          + IF(TIMEVALUE(MID(D2, FIND(\"-\", D2) + 1, LEN(D2)))\n *               <= TIMEVALUE(LEFT(D2, FIND(\"-\", D2) - 1)), 1, 0)\n *\n * The \"+ IF(...)\" on the end time handles shifts that cross midnight\n * (e.g. 22:00-06:00): without it the end lands before the start.\n *\n * Returns null for anything that isn't a shift (days off, blank cells, typos)\n * instead of throwing, so one bad cell can't stop the whole month's import.\n */\nconst SHIFT_PATTERN = /^\\s*(\\d{1,2})\\/(\\d{1,2})\\s*-\\s*(\\d{1,2}):(\\d{2})\\s*-\\s*(\\d{1,2}):(\\d{2})\\s*$/;\n\nfunction parseShift(cell, year) {\n  const m = SHIFT_PATTERN.exec(String(cell));\n  if (!m) return null;\n  const [month, day, startH, startM, endH, endM] = m.slice(1).map(Number);\n\n  if (month < 1 || month > 12 || startH > 23 || endH > 23 || startM > 59 || endM > 59) return null;\n  const start = new Date(year, month - 1, day, startH, startM);\n  // new Date() silently rolls 2/31 over to 3/3; reject instead.\n  if (start.getMonth() !== month - 1 || start.getDate() !== day) return null;\n\n  const end = new Date(year, month - 1, day, endH, endM);\n  if (end <= start) end.setDate(end.getDate() + 1); // overnight shift\n  return { start, end };\n}\n\nif (typeof module !== 'undefined') module.exports = { parseShift };\n",
 "test/parseShift.test.js": "const test = require('node:test');\nconst assert = require('node:assert/strict');\nconst { parseShift } = require('../src/parseShift.js');\n\nconst at = (y, mo, d, h, mi) => new Date(y, mo - 1, d, h, mi).getTime();\n\ntest('parses a normal day shift', () => {\n  const s = parseShift('3/31 - 13:00-21:15', 2025);\n  assert.equal(s.start.getTime(), at(2025, 3, 31, 13, 0));\n  assert.equal(s.end.getTime(), at(2025, 3, 31, 21, 15));\n});\n\ntest('overnight shift ends the next day', () => {\n  const s = parseShift('3/31 - 22:00-06:00', 2025);\n  assert.equal(s.end.getTime(), at(2025, 4, 1, 6, 0));\n});\n\ntest('overnight shift on Dec 31 rolls into the next year', () => {\n  const s = parseShift('12/31 - 23:00-07:00', 2025);\n  assert.equal(s.end.getTime(), at(2026, 1, 1, 7, 0));\n});\n\ntest('tolerates extra whitespace and single-digit hours', () => {\n  const s = parseShift('  4/2-9:00 - 17:30 ', 2025);\n  assert.equal(s.start.getTime(), at(2025, 4, 2, 9, 0));\n});\n\ntest('days off, blanks and garbage return null instead of throwing', () => {\n  for (const cell of ['3/29 - OFF', '', null, undefined, 'vacation', '3/31 - 25:00-26:00']) {\n    assert.equal(parseShift(cell, 2025), null, String(cell));\n  }\n});\n\ntest('impossible dates are rejected rather than rolled over', () => {\n  assert.equal(parseShift('2/30 - 09:00-17:00', 2025), null);\n  assert.equal(parseShift('13/1 - 09:00-17:00', 2025), null);\n});\n",
 "test/createWorkSchedule.test.js": "// Runs Code.gs against fake SpreadsheetApp / CalendarApp objects so the sync\n// logic can be tested without a Google account.\nconst test = require('node:test');\nconst assert = require('node:assert/strict');\n\nfunction fakeEnvironment(rows, { failOnRow } = {}) {\n  const written = {};\n  const created = [];\n  global.Logger = { log: () => {} };\n  global.SpreadsheetApp = {\n    getActiveSpreadsheet: () => ({\n      getActiveSheet: () => ({\n        getDataRange: () => ({ getValues: () => rows }),\n        getRange: (r, c) => ({ setValue: (v) => { written[`${r},${c}`] = v; } }),\n      }),\n    }),\n  };\n  global.CalendarApp = {\n    getDefaultCalendar: () => ({\n      createEvent: (title, start, end) => {\n        if (failOnRow !== undefined && start === rows[failOnRow][0]) throw new Error('API error');\n        created.push({ title, start, end });\n        return { addPopupReminder: () => {} };\n      },\n    }),\n  };\n  delete require.cache[require.resolve('../src/Code.gs')];\n  require.extensions['.gs'] = require.extensions['.js'];\n  const { createWorkSchedule } = require('../src/Code.gs');\n  return { run: createWorkSchedule, written, created };\n}\n\nconst d = (h) => new Date(2025, 2, 31, h);\nconst header = ['Start', 'End', 'Status'];\n\ntest('creates one event per valid row and marks it Added', () => {\n  const env = fakeEnvironment([header, [d(9), d(17), ''], [d(13), d(21), '']]);\n  assert.deepEqual(env.run(), { added: 2, skipped: 0, failed: 0 });\n  assert.equal(env.created.length, 2);\n  assert.deepEqual(env.written, { '2,3': 'Added', '3,3': 'Added' });\n});\n\ntest('re-running does not duplicate rows already marked Added', () => {\n  const env = fakeEnvironment([header, [d(9), d(17), 'Added'], [d(13), d(21), '']]);\n  assert.deepEqual(env.run(), { added: 1, skipped: 1, failed: 0 });\n});\n\ntest('skips blanks, formula errors and end-before-start rows', () => {\n  const env = fakeEnvironment([header, ['', '', ''], ['#VALUE!', d(17), ''], [d(17), d(9), '']]);\n  assert.deepEqual(env.run(), { added: 0, skipped: 3, failed: 0 });\n  assert.equal(env.created.length, 0);\n});\n\ntest('one API failure does not stop the rest, and that row stays unmarked', () => {\n  const env = fakeEnvironment([header, [d(9), d(17), ''], [d(13), d(21), '']], { failOnRow: 1 });\n  assert.deepEqual(env.run(), { added: 1, skipped: 0, failed: 1 });\n  assert.equal(env.written['2,3'], undefined);\n  assert.equal(env.written['3,3'], 'Added');\n});\n"
